mapper.select:
SELECT id, user_id, balance, created_at, updated_at
FROM pnt_account
WHERE user_id = #{userId}

mapper.update:
UPDATE pnt_account
SET balance = balance + #{delta}
WHERE user_id = #{userId}
  AND balance + #{delta} >= 0

mapper.select:
SELECT id, user_id, balance, created_at, updated_at
FROM pnt_account

    user_id = #{userId}

ORDER BY id DESC
LIMIT #{limit} OFFSET #{offset}
